#!/usr/bin/env python3
"""cpx — менеджер проектов (clone / pull / commit / push).

Реестр проектов — projects.toml рядом со скриптом:
    [projects.<имя>]
    git = "https://github.com/user/repo"
    path = "~/путь/к/папке"
"""

import argparse
import os
import sys
import tomllib

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from utils import git as gitutils

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
REGISTRY = os.path.join(BASE_DIR, "projects.toml")


def load_registry() -> dict:
    """Загрузить реестр проектов; отсутствующий/битый файл — пустой реестр."""
    if not os.path.isfile(REGISTRY):
        return {}
    try:
        with open(REGISTRY, "rb") as f:
            data = tomllib.load(f)
    except (tomllib.TOMLDecodeError, OSError) as e:
        print(f"⚠ Не удалось прочитать {REGISTRY}: {e}", file=sys.stderr)
        return {}
    projects = data.get("projects", {})
    return projects if isinstance(projects, dict) else {}


def get_project(name: str, registry: dict):
    """Вернуть (имя, git, path) или None, если проекта нет."""
    proj = registry.get(name)
    if not isinstance(proj, dict):
        return None
    return name, proj.get("git", ""), proj.get("path", "")


def cmd_install(name: str) -> int:
    registry = load_registry()
    entry = get_project(name, registry)
    if entry is None:
        print(f"✗ Проект «{name}» не найден в {REGISTRY}")
        return 1

    name, git_url, path = entry
    path = gitutils.expand(path)

    if gitutils.folder_exists(path):
        if gitutils.is_git_repo(path):
            print(f"📁 «{name}» уже установлен, выполняю pull...")
            ok, msg = gitutils.pull(path)
            if ok:
                print(f"✓ «{name}» обновлён" + (f": {msg}" if msg else ""))
                return 0
            print(f"✗ Ошибка git pull: {msg}")
            return 1
        print(f"✗ Ошибка: папка {path} существует, но не является git-репозиторием")
        return 1

    if not git_url:
        print(f"✗ У проекта «{name}» не задан git URL")
        return 1

    print(f"⬇ Клонирую «{name}» из {git_url} → {path} ...")
    ok, msg = gitutils.clone(git_url, path)
    if ok:
        print(f"✓ «{name}» установлен")
        return 0
    print(f"✗ Ошибка git clone: {msg}")
    return 1


def cmd_status(_args=None) -> int:
    registry = load_registry()
    if not registry:
        print("Реестр проектов пуст — нет проектов для отображения.")
        return 0

    headers = ("Имя", "Установлен", "Изменения", "Незапушенные")
    rows: list[list[str]] = [list(headers)]

    for name in sorted(registry):
        entry = get_project(name, registry)
        if entry is None:
            continue
        name, _, path = entry
        path = gitutils.expand(path)

        if not gitutils.is_git_repo(path):
            installed, dirty, unpushed = "нет", "—", "—"
        else:
            installed = "да"
            dirty = "есть" if gitutils.uncommitted_changes(path) else "нет"
            count = len(gitutils.unpushed_commits(path))
            unpushed = str(count) if count else "нет"

        rows.append([name, installed, dirty, unpushed])

    # Ширина колонки = максимум по заголовку и всем строкам (len(): русские
    # буквы и ASCII здесь занимают по одному символу — ширина совпадает).
    widths = [max(len(row[i]) for row in rows) for i in range(len(headers))]

    def render(cells: list[str]) -> str:
        return "  ".join(cell.ljust(widths[i]) for i, cell in enumerate(cells)).rstrip()

    print(render(rows[0]))
    print("-" * (sum(widths) + 2 * (len(widths) - 1)))
    for row in rows[1:]:
        print(render(row))

    return 0


def cmd_push(name: str) -> int:
    registry = load_registry()
    entry = get_project(name, registry)
    if entry is None:
        print(f"✗ Проект «{name}» не найден в {REGISTRY}")
        return 1

    name, _, path = entry
    path = gitutils.expand(path)

    if not gitutils.folder_exists(path):
        print(f"✗ Проект «{name}» не установлен (папки {path} нет)")
        return 1
    if not gitutils.is_git_repo(path):
        print(f"✗ Ошибка: папка {path} не является git-репозиторием")
        return 1

    print(f"⬆ Отправляю «{name}»...")
    ok, msg = gitutils.push(path)
    if ok:
        print(f"✓ «{name}»: {msg}")
        return 0
    print(f"✗ «{name}»: {msg}")
    return 1


def cmd_pushall(_args=None) -> int:
    registry = load_registry()
    if not registry:
        print("Реестр проектов пуст — нет проектов для отправки.")
        return 0

    failed = 0
    for name in sorted(registry):
        if cmd_push(name) != 0:
            failed += 1

    if failed:
        print(f"\n⚠ Завершено с ошибками: {failed} из {len(registry)}")
        return 1
    print(f"\n✓ Все проекты ({len(registry)}) отправлены")
    return 0


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(
        prog="cpx",
        description="cpx — менеджер проектов (clone / pull / commit / push).",
    )
    sub = parser.add_subparsers(dest="command", metavar="команда")

    p_install = sub.add_parser("install", help="установить или обновить проект (clone/pull)")
    p_install.add_argument("name", help="имя проекта из projects.toml")

    sub.add_parser("status", help="таблица состояния всех проектов")

    p_push = sub.add_parser("push", help="закоммитить («cpx: sync») и отправить изменения")
    p_push.add_argument("name", help="имя проекта из projects.toml")

    sub.add_parser("pushall", help="push по всем проектам")

    args = parser.parse_args(argv)

    if args.command == "install":
        return cmd_install(args.name)
    if args.command == "status":
        return cmd_status()
    if args.command == "push":
        return cmd_push(args.name)
    if args.command == "pushall":
        return cmd_pushall()

    parser.print_help()
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""Git-операции для cpx.

Все функции принимают путь к папке проекта (расширять через os.path.expanduser
до вызова или внутри — здесь расширяем для надёжности).
"""

import os
import subprocess

# Все git-операции гоним по SSH, даже если URL в projects.toml / remote — HTTPS.
# Флаг вместоOf подменяет HTTPS→SSH на лету, не изменяя remote и конфиг репозитория.
GIT_PREFIX = [
    "git",
    "-c",
    'url."git@github.com:".insteadOf="https://github.com/"',
]


def _run(args, cwd=None):
    """Запуск git-команды: возвращает CompletedProcess (без исключений)."""
    return subprocess.run(
        args,
        cwd=os.path.expanduser(cwd) if cwd else None,
        capture_output=True,
        text=True,
    )


def _git(*args, cwd=None):
    """git-команда с подменой HTTPS→SSH (через GIT_PREFIX)."""
    return _run(GIT_PREFIX + list(args), cwd=cwd)


def expand(path: str) -> str:
    """Расширить ~ и переменные окружения в пути."""
    return os.path.expanduser(os.path.expandvars(path))


def is_git_repo(path: str) -> bool:
    """Папка существует и внутри есть .git (репозиторий)."""
    path = expand(path)
    return os.path.isdir(path) and os.path.isdir(os.path.join(path, ".git"))


def folder_exists(path: str) -> bool:
    """Папка существует (не обязательно репозиторий)."""
    return os.path.isdir(expand(path))


def clone(git_url: str, path: str) -> tuple[bool, str]:
    """git clone <url> <path>. Возвращает (успех, сообщение)."""
    path = expand(path)
    result = _git("clone", git_url, path)
    if result.returncode != 0:
        return False, (result.stderr or result.stdout).strip()
    return True, ""


def pull(path: str) -> tuple[bool, str]:
    """git pull в папке проекта. Возвращает (успех, сообщение)."""
    result = _git("pull", cwd=path)
    if result.returncode != 0:
        return False, (result.stderr or result.stdout).strip()
    return True, (result.stdout or "").strip()


def has_upstream(path: str) -> bool:
    """Есть ли upstream у текущей ветки (git rev-parse --abbrev-ref @{u})."""
    result = _git("rev-parse", "--abbrev-ref", "@{u}", cwd=path)
    return result.returncode == 0


def uncommitted_changes(path: str) -> bool:
    """Есть ли несохранённые изменения (git status --porcelain непуст)."""
    result = _git("status", "--porcelain", cwd=path)
    if result.returncode != 0:
        return False
    return bool(result.stdout.strip())


def unpushed_commits(path: str) -> list[str]:
    """Незапушенные коммиты (git log @{u}.. --oneline); без upstream — []."""
    if not has_upstream(path):
        return []
    result = _git("log", "@{u}..", "--oneline", cwd=path)
    if result.returncode != 0:
        return []
    return [line for line in result.stdout.splitlines() if line.strip()]


def push(path: str) -> tuple[bool, str]:
    """git add -A; commit «cpx: sync» при staged-изменениях; push при upstream.

    Возвращает (успех, сообщение).
    """
    path = expand(path)
    if not is_git_repo(path):
        return False, "не git-репозиторий"

    # git add -A
    result = _git("add", "-A", cwd=path)
    if result.returncode != 0:
        return False, "git add: " + (result.stderr or result.stdout).strip()

    # есть ли staged-изменения?
    diff = _git("diff", "--cached", "--quiet", cwd=path)
    if diff.returncode != 0:  # 1 = изменения есть
        commit = _git("commit", "-m", "cpx: sync", cwd=path)
        if commit.returncode != 0:
            return False, "git commit: " + (commit.stderr or commit.stdout).strip()

    # push только если есть upstream
    if has_upstream(path):
        result = _git("push", cwd=path)
        if result.returncode != 0:
            return False, "git push: " + (result.stderr or result.stdout).strip()
        return True, "изменения отправлены"

    return True, "изменения закоммичены (upstream не задан — push пропущен)"
